static int cb_list(void *user, const char *k, const char *v) {
        RAnal *a = (RAnal*)user;
        if (*k == '0') {
                // bind
                a->cb_printf ("%s = %s\n", k, v);
        } else {
                // ptr
                a->cb_printf ("PIN %s\n", k);
        }
        return true;
}

R_API void r_anal_pin_list(RAnal *a) {
        sdb_foreach (DB, cb_list, a);
